add_filter( 'block_editor_settings_all', 'perfectpixel_editor_default_image_size_block' );
add_filter( 'pre_option_image_default_size', 'perfectpixel_editor_default_image_size_option' );

function perfectpixel_editor_default_image_size_name() {
	$size = sanitize_key( '{{editor_default_image_size}}' );
	return $size ? $size : 'full';
}

function perfectpixel_editor_default_image_size_block( $settings ) {
	$settings['imageDefaultSize'] = perfectpixel_editor_default_image_size_name();
	return $settings;
}

// Used by the classic editor's media modal.
function perfectpixel_editor_default_image_size_option() {
	return perfectpixel_editor_default_image_size_name();
}
